<?php
declare(strict_types=1);
namespace KodVadAll\Modules\Service;
use PDO;
use RuntimeException;
use Throwable;
use KodVadAll\Core\NotificationService;
final class ServiceController
{
 public static function handle(PDO $db,array $admin):void
 {
  kd_require_permission('service.view');$errors=[];$success='';$id=(int)($_GET['id']??0);
  if($_SERVER['REQUEST_METHOD']==='POST'){kd_csrf_check();kd_require_permission('service.manage');$action=(string)($_POST['form_action']??'');try{
   if($action==='create'){$device=trim((string)($_POST['device_name']??''));$issue=trim((string)($_POST['issue_description']??''));if($device===''||$issue==='')throw new RuntimeException('Cihaz ve arıza açıklaması zorunludur.');$temp='TMP-SRV-'.bin2hex(random_bytes(4));$db->prepare("INSERT INTO service_jobs (service_number,customer_id,device_name,serial_number,issue_description,status,priority,assigned_user_id,estimated_cost,received_at,due_at,created_by,created_at) VALUES (?,?,?,?,?,'received',?,?,?,?,?,?,NOW())")->execute([$temp,(int)($_POST['customer_id']??0)?:null,$device,trim((string)($_POST['serial_number']??''))?:null,$issue,in_array($_POST['priority']??'', ['low','normal','high','urgent'],true)?$_POST['priority']:'normal',(int)($_POST['assigned_user_id']??0)?:null,max(0,(float)($_POST['estimated_cost']??0)),date('Y-m-d H:i:s'),trim((string)($_POST['due_at']??''))?:null,(int)$admin['id']]);$id=(int)$db->lastInsertId();$number='SRV-'.date('Y').'-'.str_pad((string)$id,6,'0',STR_PAD_LEFT);$db->prepare('UPDATE service_jobs SET service_number=? WHERE id=?')->execute([$number,$id]);$db->prepare('INSERT INTO service_job_history (service_job_id,user_id,from_status,to_status,note,created_at) VALUES (?,?,NULL,?,?,NOW())')->execute([$id,(int)$admin['id'],'received','Servis kaydı açıldı']);kd_audit('service.created','service_job',$id);NotificationService::notifyRoles($db,['owner','admin','manager'],'Yeni teknik servis kaydı',$number.' · '.$device,'index.php?page=service&id='.$id,'info');$success='Servis kaydı oluşturuldu.';}
   if($action==='update'){$jobId=(int)($_POST['job_id']??0);$status=in_array($_POST['status']??'', ['received','diagnosing','waiting_parts','in_progress','ready','delivered','cancelled'],true)?$_POST['status']:'received';$q=$db->prepare('SELECT status FROM service_jobs WHERE id=?');$q->execute([$jobId]);$old=(string)$q->fetchColumn();if($old==='')throw new RuntimeException('Servis kaydı bulunamadı.');$db->beginTransaction();if($status==='delivered'){$q=$db->prepare('SELECT * FROM service_jobs WHERE id=? FOR UPDATE');$q->execute([$jobId]);$job=$q->fetch();if(empty($job['stock_deducted_at'])){$q=$db->prepare('SELECT * FROM service_job_parts WHERE service_job_id=?');$q->execute([$jobId]);$parts=$q->fetchAll();foreach($parts as $part){$p=$db->prepare('SELECT * FROM products WHERE id=? FOR UPDATE');$p->execute([(int)$part['product_id']]);$product=$p->fetch();if(!$product)throw new RuntimeException('Servis parçası bulunamadı.');if((int)$product['track_stock']&&(float)$product['stock_quantity']<(float)$part['quantity'])throw new RuntimeException('Yetersiz stok: '.$product['name']);if((int)$product['track_stock']){$before=(float)$product['stock_quantity'];$after=$before-(float)$part['quantity'];$db->prepare('UPDATE products SET stock_quantity=?,updated_at=NOW() WHERE id=?')->execute([$after,(int)$product['id']]);$db->prepare("INSERT INTO product_stock_movements (product_id,user_id,movement_type,quantity,before_quantity,after_quantity,note,reference_type,reference_id,created_at) VALUES (?,?,'out',?,?,?,?, 'service',?,NOW())")->execute([(int)$product['id'],(int)$admin['id'],$part['quantity'],$before,$after,'Servis '.$job['service_number'],$jobId]);}}$db->prepare('UPDATE service_jobs SET stock_deducted_at=NOW(),actual_cost=(SELECT COALESCE(SUM(line_total),0) FROM service_job_parts WHERE service_job_id=?) WHERE id=?')->execute([$jobId,$jobId]);}}
    $db->prepare('UPDATE service_jobs SET status=?,diagnosis=?,resolution=?,assigned_user_id=?,delivered_at=IF(?=\'delivered\',NOW(),delivered_at),updated_at=NOW() WHERE id=?')->execute([$status,trim((string)($_POST['diagnosis']??''))?:null,trim((string)($_POST['resolution']??''))?:null,(int)($_POST['assigned_user_id']??0)?:null,$status,$jobId]);$db->prepare('INSERT INTO service_job_history (service_job_id,user_id,from_status,to_status,note,created_at) VALUES (?,?,?,?,?,NOW())')->execute([$jobId,(int)$admin['id'],$old,$status,trim((string)($_POST['note']??''))?:null]);$db->commit();$id=$jobId;$success='Servis durumu güncellendi.';}
   if($action==='part'){$jobId=(int)($_POST['job_id']??0);$productId=(int)($_POST['product_id']??0);$qty=(float)($_POST['quantity']??0);if($qty<=0)throw new RuntimeException('Parça miktarı geçersiz.');$q=$db->prepare("SELECT status FROM service_jobs WHERE id=?");$q->execute([$jobId]);if(!in_array($q->fetchColumn(),['received','diagnosing','waiting_parts','in_progress'],true))throw new RuntimeException('Bu servis kaydına parça eklenemez.');$q=$db->prepare("SELECT id,name,sale_price FROM products WHERE id=? AND status='active'");$q->execute([$productId]);$p=$q->fetch();if(!$p)throw new RuntimeException('Ürün bulunamadı.');$db->prepare('INSERT INTO service_job_parts (service_job_id,product_id,product_name,quantity,unit_price,line_total,created_at) VALUES (?,?,?,?,?,?,NOW())')->execute([$jobId,$productId,$p['name'],$qty,$p['sale_price'],$qty*(float)$p['sale_price']]);$id=$jobId;$success='Servis parçası eklendi.';}
  }catch(Throwable $e){if($db->inTransaction())$db->rollBack();$errors[]=$e instanceof RuntimeException?$e->getMessage():'Servis işlemi tamamlanamadı.';}}
  $customers=$db->query("SELECT id,name FROM customers WHERE status='active' ORDER BY name LIMIT 500")->fetchAll();$users=$db->query("SELECT id,name FROM users WHERE status='active' ORDER BY name")->fetchAll();$products=$db->query("SELECT id,name,sku,sale_price,stock_quantity FROM products WHERE status='active' ORDER BY name")->fetchAll();
  if($id){$q=$db->prepare('SELECT j.*,c.name customer_name,u.name assignee_name FROM service_jobs j LEFT JOIN customers c ON c.id=j.customer_id LEFT JOIN users u ON u.id=j.assigned_user_id WHERE j.id=?');$q->execute([$id]);$job=$q->fetch();if(!$job)throw new RuntimeException('Servis kaydı bulunamadı.');$q=$db->prepare('SELECT * FROM service_job_parts WHERE service_job_id=?');$q->execute([$id]);$parts=$q->fetchAll();$q=$db->prepare('SELECT h.*,u.name user_name FROM service_job_history h LEFT JOIN users u ON u.id=h.user_id WHERE h.service_job_id=? ORDER BY h.id DESC');$q->execute([$id]);$history=$q->fetchAll();}
  else{$jobs=$db->query('SELECT j.*,c.name customer_name,u.name assignee_name FROM service_jobs j LEFT JOIN customers c ON c.id=j.customer_id LEFT JOIN users u ON u.id=j.assigned_user_id ORDER BY j.id DESC LIMIT 150')->fetchAll();}
  $pageTitle='Teknik Servis';ob_start();require KD_ROOT.'/app/Views/service/index.php';$content=ob_get_clean();require KD_ROOT.'/app/Views/layouts/admin.php';
 }
}
